// ═══════════════════════════════════════════════════════════════
// Extract Email Data - V2 (WITH ATTACHMENTS)
// Purpose: Extract all text content, metadata AND attachments
// ═══════════════════════════════════════════════════════════════

function b64urlToB64(u) {
  if (!u) return '';
  let s = String(u).replace(/-/g, '+').replace(/_/g, '/');
  while (s.length % 4) s += '=';
  return s;
}

function decodeQP(s) {
  if (!s) return '';
  s = s.replace(/=\r?\n/g, '');
  return s.replace(/=([A-Fa-f0-9]{2})/g, (_, h) => String.fromCharCode(parseInt(h, 16)));
}

function decodeEncodedWords(s) {
  if (!s) return s;
  return s.replace(/=\?([\w\-]+)\?(Q|B)\?([\s\S]*?)\?=/gi, (_, cs, enc, txt) => {
    try {
      if (enc.toUpperCase() === 'B') {
        return Buffer.from(txt.replace(/\s+/g, ''), 'base64').toString('utf8');
      }
      return decodeQP(txt.replace(/_/g, ' '));
    } catch { return txt; }
  });
}

function splitHeaderBody(rfc822) {
  const m = String(rfc822).replace(/\r/g, '').split('\n\n');
  return { headerBlock: m[0] || '', bodyBlock: m.slice(1).join('\n\n') || '' };
}

function unfoldHeaders(hdr) {
  const lines = String(hdr || '').replace(/\r/g, '').split('\n');
  const merged = [];
  for (const l of lines) {
    if (/^\s/.test(l) && merged.length) merged[merged.length - 1] += ' ' + l.trim();
    else if (l.trim() !== '') merged.push(l);
  }
  const map = {};
  for (const l of merged) {
    const i = l.indexOf(':');
    if (i > -1) {
      const k = l.slice(0, i).trim().toLowerCase();
      const v = decodeEncodedWords(l.slice(i + 1).trim());
      map[k] = v;
    }
  }
  return map;
}

function getBoundary(ct) {
  const m = /boundary="?([^";]+)"?/i.exec(ct || '');
  return m ? m[1] : null;
}

function splitMultipart(body, boundary) {
  const lines = String(body || '').replace(/\r/g, '').split('\n');
  const start = '--' + boundary, end = '--' + boundary + '--';
  const parts = [];
  let cur = [], inside = false;
  for (const line of lines) {
    if (line === start) {
      if (inside && cur.length) { parts.push(cur.join('\n')); cur = []; }
      inside = true;
      continue;
    }
    if (line === end) {
      if (inside && cur.length) parts.push(cur.join('\n'));
      inside = false;
      break;
    }
    if (inside) cur.push(line);
  }
  if (inside && cur.length) parts.push(cur.join('\n'));
  return parts;
}

function parseLeafBody(headers, rawBody) {
  let body = rawBody || '';
  const cte = String(headers['content-transfer-encoding'] || '').toLowerCase();
  if (cte.includes('base64')) {
    try {
      const clean = body.replace(/\s+/g, '');
      body = Buffer.from(clean, 'base64').toString('utf8');
    } catch { }
  } else if (cte.includes('quoted-printable')) {
    body = decodeQP(body);
  }
  return body;
}

function stripHtml(html) {
  return String(html || '').replace(/<style[\s\S]*?<\/style>|<script[\s\S]*?<\/script>/gi, '').replace(/<\/?[^>]+>/g, ' ');
}

// ═══ ATTACHMENT UTILITIES (from v1) ═══

function parseParams(v) {
  const out = { value: v, params: {} };
  if (!v) return out;
  const [val, ...rest] = v.split(';');
  out.value = val.trim();
  for (const seg of rest) {
    const m = /([^=]+)=(.*)/.exec(seg.trim());
    if (!m) continue;
    let key = m[1].toLowerCase().trim(), val2 = m[2].trim().replace(/^"(.*)"$/, '$1');
    // RFC5987 filename*: utf-8''encoded
    if (/^\w+\*\s*$/.test(key)) {
      key = key.replace('*', '');
      const mm = /^([^']*)''(.*)$/.exec(val2);
      if (mm) {
        try { val2 = decodeURIComponent(mm[2]); } catch { }
      }
    }
    out.params[key] = val2;
  }
  out.filename = out.params.filename || out.params.name || null;
  return out;
}

function calcSizeBytes(b64) {
  if (!b64) return 0;
  const eq = b64.endsWith('==') ? 2 : b64.endsWith('=') ? 1 : 0;
  return Math.max(0, Math.floor(b64.length * 3 / 4) - eq);
}

// Simplified SHA-256 (pure JS)
function rotr(x, n) { return (x >>> n) | (x << (32 - n)); }
function sha256Hex(buf) {
  const K = new Uint32Array([0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2]);
  const H = new Uint32Array([0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19]);
  const bytes = (buf instanceof Uint8Array) ? buf : new Uint8Array(buf);
  const len = bytes.length, bitLen = len * 8, total = (((len + 9) + 63) >> 6) << 6, pad = new Uint8Array(total);
  pad.set(bytes); pad[len] = 0x80;
  const dv = new DataView(pad.buffer); dv.setUint32(total - 8, Math.floor(bitLen / 0x100000000), false); dv.setUint32(total - 4, bitLen >>> 0, false);
  const w = new Uint32Array(64);
  for (let i = 0; i < total; i += 64) {
    for (let j = 0; j < 16; j++) w[j] = dv.getUint32(i + j * 4, false);
    for (let j = 16; j < 64; j++) {
      const s0 = rotr(w[j - 15], 7) ^ rotr(w[j - 15], 18) ^ (w[j - 15] >>> 3);
      const s1 = rotr(w[j - 2], 17) ^ rotr(w[j - 2], 19) ^ (w[j - 2] >>> 10);
      w[j] = (w[j - 16] + s0 + w[j - 7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let j = 0; j < 64; j++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[j] + w[j]) >>> 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    H[0] = (H[0] + a) >>> 0; H[1] = (H[1] + b) >>> 0; H[2] = (H[2] + c) >>> 0; H[3] = (H[3] + d) >>> 0;
    H[4] = (H[4] + e) >>> 0; H[5] = (H[5] + f) >>> 0; H[6] = (H[6] + g) >>> 0; H[7] = (H[7] + h) >>> 0;
  }
  let hex = ''; for (let i = 0; i < 8; i++) hex += ('00000000' + H[i].toString(16)).slice(-8);
  return hex;
}

// ═══ MODIFIED walkEntity to extract attachments ═══

function walkEntity(entityText, out, inheritedCT) {
  const { headerBlock, bodyBlock } = splitHeaderBody(entityText);
  const H = unfoldHeaders(headerBlock);
  const ct = (H['content-type'] || inheritedCT || '').toLowerCase();
  const disp = (H['content-disposition'] || '').toLowerCase();

  if (/^multipart\//.test(ct)) {
    const boundary = getBoundary(ct);
    if (boundary) {
      for (const part of splitMultipart(bodyBlock, boundary)) {
        walkEntity(part, out, ct);
      }
    }
    return;
  }

  // Leaf node
  const bodyDecoded = parseLeafBody(H, bodyBlock);
  const pCT = parseParams(ct);
  const isTextPlain = pCT.value.includes('text/plain');
  const isTextHtml = pCT.value.includes('text/html');

  // Extract filename from Content-Disposition or Content-Type
  const params = parseParams(disp);
  let filename = params.filename || parseParams(ct).filename || null;
  if (!filename && /attachment/.test(disp)) filename = 'attachment.bin';

  // Detect attachment
  const isAttachment = /attachment/.test(disp) || (!!filename && !isTextPlain && !isTextHtml);
  const cte = String(H['content-transfer-encoding'] || '').toLowerCase();
  const cid = (H['content-id'] || '').replace(/[<>]/g, '');

  if (isAttachment) {
    // Calculate size and hash
    let size_bytes = 0, sha256 = null;
    if (cte.includes('base64')) {
      const clean = bodyBlock.replace(/\s+/g, '');
      size_bytes = calcSizeBytes(clean);
      try { sha256 = sha256Hex(Buffer.from(clean, 'base64')); } catch { }
    } else {
      size_bytes = Buffer.from(bodyDecoded, 'utf8').length;
      try { sha256 = sha256Hex(Buffer.from(bodyDecoded, 'utf8')); } catch { }
    }

    out.attachments.push({
      filename: filename || null,
      mime_type: pCT.value || 'application/octet-stream',
      size_bytes,
      sha256,
      cid: cid || null,
      content_id: cid || null,
    });
  } else {
    if (isTextPlain) out.texts.push(bodyDecoded);
    if (isTextHtml) out.htmls.push(bodyDecoded);
    if (!isTextPlain && !isTextHtml && !disp) {
      out.texts.push(bodyDecoded);
    }
  }
}

// ═══ MAIN ═══
const item = $input.item.json;

let rawB64 = '';
if (item.raw) {
  rawB64 = b64urlToB64(item.raw);
} else if (item.payload && item.payload.raw) {
  rawB64 = b64urlToB64(item.payload.raw);
} else {
  return {
    json: {
      error: 'No raw RFC822 data found',
      email_id: item.id || null,
      thread_id: item.threadId || null,
      from: null,
      to: null,
      subject: '',
      date: new Date().toISOString(),
      body_text: '',
      body_html: '',
      headers: {},
      full_text: '',
      attachments: []
    }
  };
}

const rawDecoded = Buffer.from(rawB64, 'base64').toString('utf-8');
const { headerBlock, bodyBlock } = splitHeaderBody(rawDecoded);
const topH = unfoldHeaders(headerBlock);

const acc = { texts: [], htmls: [], attachments: [] }; // ← Added attachments
walkEntity(rawDecoded, acc, topH['content-type'] || '');

const textContent = (acc.texts.find(s => s && s.trim()) || '').trim();
const htmlContent = (acc.htmls.find(s => s && s.trim()) || '').trim();
const fullText = textContent + '\n' + stripHtml(htmlContent);

const emailId = item.id || item.messageId;
const threadId = item.threadId;
const subject = topH['subject'] || '';
const from = topH['from'] || null;
const to = topH['to'] || null;
const date = topH['date'] || new Date().toISOString();

const headers = {};
for (const [k, v] of Object.entries(topH)) {
  headers[k] = v;
}

return {
  json: {
    email_id: emailId,
    thread_id: threadId,
    from: from,
    to: to,
    subject: subject,
    date: date,
    body_text: textContent,
    body_html: htmlContent,
    headers: headers,
    full_text: (subject || '') + '\n\n' + fullText,
    attachments: acc.attachments, // ← Return attachments
    has_attachments: acc.attachments.length > 0,
    attachment_count: acc.attachments.length
  }
};

// ═══════════════════════════════════════════════════════════════
// Prepare Payload for /ingest/raw endpoint - V4 WITH THREADING HEADERS
// Purpose: Prepare data for POST /api/v1/communication/ingest/raw
// FIXED: Convert base64url (Gmail) to base64 standard (backend)
// FIXED: Add thread_id and provider_msg_id for threading support
// FIXED: Attachments at ROOT level (not in parsed)
// NEW: Extract In-Reply-To and References headers to ROOT level for threading
// ═══════════════════════════════════════════════════════════════

// const emailData = $('Extract Email Data').first().json;
// const gmailRaw = $('Gmail Get Raw Message').first().json;
// const gmailTrigger = $('Gmail Trigger').first().json;

const mergedItem = $('Loop Over Items').first().json;
const emailData = mergedItem;
const gmailRaw = mergedItem._gmail_raw;
const gmailTrigger = mergedItem._gmail_trigger;

const tokenData = $input.first().json;
const token = tokenData.access_token;

// Convert base64url to base64 (Gmail API returns base64url, backend expects base64)
function b64urlToB64(u) {
  if (!u) return '';
  let s = String(u).replace(/-/g, '+').replace(/_/g, '/');
  while (s.length % 4) s += '=';
  return s;
}

// Gmail account ID from fixtures (active n8n Gmail account)
const accountId = '12b3f7b4-8fb1-4830-82d5-58d7fd874d2a';

// Get raw RFC822 from Gmail API and convert base64url to base64
const rawSourceB64 = b64urlToB64(gmailRaw.raw || '');

// Get Gmail threading metadata
const gmailMessageId = gmailTrigger.id || null;        // Gmail Message ID
const gmailThreadId = gmailTrigger.threadId || null;    // Gmail Thread ID

// Get attachments from Extract Email Data
const attachments = emailData.attachments || [];
const hasAttachments = emailData.has_attachments || false;
const attachmentCount = emailData.attachment_count || 0;

// Extract threading headers from email headers
const headers = emailData.headers || {};
const inReplyTo = headers['in-reply-to'] || null;
const references = headers['references'] || null;
const messageId = headers['message-id'] || null;

console.log('🧵 Threading info:');
console.log('  Message-ID:', messageId);
console.log('  In-Reply-To:', inReplyTo);
console.log('  References:', references);
console.log('  Gmail Thread ID:', gmailThreadId);

console.log('📎 Attachments detected:', attachmentCount);
if (attachments.length > 0) {
  attachments.forEach((att, idx) => {
    console.log(`  ${idx + 1}. ${att.filename} (${att.mime_type}, ${att.size_bytes} bytes, SHA256: ${att.sha256?.substring(0,16)}...)`);
  });
}

// Prepare payload for /ingest/raw endpoint
// IMPORTANT: In-Reply-To and References MUST be at root level for backend threading
const payload = {
  account_id: accountId,
  raw_source_rfc822_b64: rawSourceB64,
  ts_received: emailData.date || new Date().toISOString(),
  channel: 'email',
  rspamd: { score: 0, symbols: ['N8N'] },
  score_risk: 50,
  thread_id: gmailThreadId,           // Gmail Thread ID for threading
  provider_msg_id: gmailMessageId,    // Gmail Message ID for reply operations
  in_reply_to: inReplyTo,             // ← In-Reply-To header for threading
  references: references,              // ← References header for threading
  message_id: messageId,               // ← Message-ID header
  attachments: attachments,            // ← AT ROOT LEVEL (backend expects this)
  parsed: {                            // Optional parsed structure
    headers: emailData.headers || {},
    body: {
      text: emailData.body_text || '',
      html: emailData.body_html || '',
      has_attachments: hasAttachments,
      attachment_count: attachmentCount,
      text_length: (emailData.body_text || '').length,
      html_length: (emailData.body_html || '').length,
    }
  }
};

console.log('✓ Payload prepared with threading headers at root level');
console.log('✓ Attachments:', attachmentCount);

return {
  json: {
    token: token,
    payload: payload,
    email_id: emailData.email_id,
    full_text: emailData.full_text
  }
};

// Extract conv_id and msg_id from Ingest Email response
const ingestData = $('Ingest Email').first().json;
const riskData = $input.first().json;

return {
  json: {
    conv_id: ingestData.conv_id,
    last_msg_id: ingestData.msg_id,
    scam_category: riskData.category || 'Credential_phish',
    reason: 'auto_draft_on_inbound'
  }
};

const ingestData = $('Ingest Email').first().json;
const riskData = $('Get Risk Assessment').first().json;
return {
  json: {
    status: 'processed_no_reply',
    msg_id: ingestData.msg_id,
    conv_id: ingestData.conv_id,
    risk_level: riskData.risk_level,
    should_reply: riskData.should_reply,
    reply_generated: false,
    reason: 'Low risk, no exploitable artefacts',
    timestamp: new Date().toISOString()
  }
};

// ═══════════════════════════════════════════════════════════════
// Prepare for WF-ANALYZE-IOC - CORRECTED
// Purpose: Extract msg_id from backend response (NOT Gmail email_id)
// and prepare data for IOC extraction workflow
// ═══════════════════════════════════════════════════════════════

const ingestResponse = $('Ingest Email').first().json;
// const emailData = $('Extract Email Data').first().json;
const emailData = $('Loop Over Items').first().json;
const prepareData = $('Prepare Payload').first().json;

// IMPORTANT: Use backend msg_id (UUID), not Gmail email_id
// The backend message MUST exist before WF-ANALYZE-IOC runs
return {
  json: {
    msg_id: ingestResponse.msg_id,  // ← Backend UUID (REQUIRED by POST /iocs/enriched)
    body_text: emailData.body_text,
    subject: emailData.subject,
    headers: emailData.headers,
    full_text: prepareData.full_text
  }
};

const triggerItems = $('Gmail Trigger').all();
const rawItems = $('Gmail Get Raw Message').all();
const extractedItems = $('Extract Email Data').all();

const merged = [];
for (let i = 0; i < extractedItems.length; i++) {
  merged.push({
    json: {
      ...extractedItems[i].json,
      _gmail_raw: rawItems[i]?.json || {},
      _gmail_trigger: triggerItems[i]?.json || {},
    }
  });
}
return merged;
